content.query:
_Im_NetworkSession
| where TimeGenerated {TimeRange}
| where EventVendor =~ 'Zscaler' and EventProduct has 'Private Access'
| make-series TotalEvents = count() default = 0 on TimeGenerated from {TimeRange:start} to {TimeRange:end} step {TimeRange:grain};

let Base = materialize(
    _Im_NetworkSession
    | where TimeGenerated {TimeRange}
    | where EventVendor =~ 'Zscaler' and EventProduct has 'Private Access'
    | where isnotempty(SrcUsername)
);
Base
| summarize TrafficVolume = sum(tolong(SrcBytes)) by SrcUsername
| join kind=inner (
    Base
    | make-series Trend = count() default = 0 on TimeGenerated from {TimeRange:start} to {TimeRange:end} step {TimeRange:grain} by SrcUsername
) on SrcUsername
| project User = SrcUsername, ['Traffic(MB)'] = TrafficVolume / 1000000.0, Trend
| order by ['Traffic(MB)'] asc
| take 8

let Lookback = 30d;
let CurrentWindow = 24h;
let Base = materialize(
    _Im_NetworkSession
    | where TimeGenerated > ago(Lookback)
    | where EventVendor =~ 'Zscaler' and EventProduct has 'Private Access'
);
let Baseline = Base
    | where TimeGenerated between (ago(Lookback) .. ago(CurrentWindow))
    | where DvcAction == 'Allow'
    | summarize by SrcUsername, SrcIpAddr;
let Current = Base
    | where TimeGenerated > ago(CurrentWindow)
    | where isnotempty(SrcUsername) and isnotempty(SrcIpAddr)
    | summarize EventCount = count() by SrcUsername, SrcIpAddr;
Current
| join kind=leftanti (Baseline) on SrcUsername, SrcIpAddr
| extend Message = 'VPN connection from new IP'
| project User = SrcUsername, SrcIpAddr, Message
